// New customer check (runs before anything is written): Eclipse address
// validation plus a HubSpot duplicate search. GET, so it is safe to test.
const q = $input.first().json.query || {};
const s = (v) => String(v == null ? '' : v).trim();
const input = {
  name: s(q.name),
  domain: s(q.domain).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, ''),
  address: s(q.address),
  address2: s(q.address2),
  city: s(q.city),
  state: s(q.state).toUpperCase(),
  zip: s(q.zip).replace(/[\s-]/g, ''),
  // What is being created (bill_to;ship_to): duplicates are only records
  // of the same kind (Shape). Empty means no filter.
  flags: s(q.billto_shipto_flag).split(/[;,]/).map(s).filter((f) => f === 'bill_to' || f === 'ship_to'),
};
const missing = ['address', 'city', 'state', 'zip'].filter((k) => !input[k]);
if (missing.length) return [{ json: { ok: false, statusCode: 400, body: { error: 'Missing ' + missing.join(', ') } } }];

// Duplicate search: same zip (5 digits, and the full zip when longer) or
// the same domain. Name matches come from a second, free-text search.
const zip5 = input.zip.slice(0, 5);
const groups = [{ filters: [{ propertyName: 'zip', operator: 'EQ', value: zip5 }] }];
if (input.zip !== zip5) groups.push({ filters: [{ propertyName: 'zip', operator: 'EQ', value: input.zip }] });
if (input.domain) groups.push({ filters: [{ propertyName: 'domain', operator: 'EQ', value: input.domain }] });

// Google Address Validation request (v1:validateAddress). The page's State
// list also has Canadian provinces; USPS CASS is US / PR only.
const CA = ['AB', 'BC', 'MB', 'NB', 'NL', 'NS', 'NT', 'NU', 'ON', 'PE', 'QC', 'SK', 'YT'];
const regionCode = CA.includes(input.state) ? 'CA' : input.state === 'PR' ? 'PR' : 'US';
const google = {
  address: {
    regionCode,
    addressLines: [input.address, input.address2].filter(Boolean),
    locality: input.city,
    administrativeArea: input.state,
    postalCode: input.zip,
  },
};
if (regionCode !== 'CA') google.enableUspsCass = true;

return [{ json: { ok: true, input, filter: { filterGroups: groups }, google } }];

// Shapes the address check and the duplicate list for the page.
// address: { ok, errors: [text], suggestion: { address, address2, city,
//   cities: [..], state, zip, source: 'eclipse' | 'google' } | null,
//   unavailable, unconfirmed, message, location: { lat, lng } | null,
//   google: { checked, confirmed, granularity } }
// ok / errors / unavailable are Eclipse's (it refuses a city / state that
// does not match the zip); Google adds the standardized address
// (suggestion), whether the street address exists (unconfirmed, message)
// and its coordinates (location).
// duplicates: [{ e_customer_id, hs_id, name, address, reasons: [..] }]
const input = $('Validate').first().json.input;
const s = (v) => String(v == null ? '' : v).trim();
const same = (a, b) => s(a).toUpperCase() === s(b).toUpperCase();

// ── Address ────────────────────────────────────────────────────────────
const a = $('Eclipse: validate address').first().json || {};
const address = { ok: false, errors: [], suggestion: null, unavailable: false };
if (Array.isArray(a.errors) && a.errors.length) {
  // A 400: the address failed. Eclipse's message can name the right
  // city / state for the zip, e.g. Invalid City/State/Country for
  // PostalCode "44146". Should be City: "BEDFORD, ...", State: "OH", Country: "".
  address.errors = a.errors.map((e) => s(e && (e.message || e))).filter(Boolean);
  const text = address.errors.join(' ');
  const city = (text.match(/City:\s*"([^"]*)"/i) || [])[1] || '';
  const state = (text.match(/State:\s*"([^"]*)"/i) || [])[1] || '';
  // Several cities read "BEDFORD, or BEDFORD HEIGHTS, or CLEVELAND" (live
  // GET, 2026-10-29).
  const cities = city.split(',').map((c) => s(c).replace(/^or\s+/i, '')).filter((c) => c && !/^\.+$/.test(c));
  if (cities.length || state) {
    address.suggestion = {
      address: input.address, address2: input.address2,
      city: cities[0] || input.city, cities,
      state: state || input.state, zip: input.zip, source: 'eclipse',
    };
  }
} else if (a.error) {
  // Any other failure (Eclipse down, 5xx): the page shows it and lets the
  // rep create without the check.
  address.unavailable = true;
  address.errors = ['Eclipse address check failed: ' + s(a.error) + (a.message ? ' ' + JSON.stringify(a.message).slice(0, 300) : '')];
} else {
  // Success: Eclipse answers { results: [{ streetLineOne, city, state,
  // postalCode, ... }] } with the address as sent (live, 2026-10-29), so
  // there is nothing to suggest from it.
  address.ok = true;
}

// ── Google Address Validation ──────────────────────────────────────────
// Best-effort: no key, a quota error or Google down leaves the Eclipse
// result alone (google.checked false, message says why).
// Field names checked against live answers (2026-10-30: a premise match
// with uspsData, a typo, and an RR route that came back OTHER).
const g = $('Google: validate address').first().json || {};
address.google = { checked: false, confirmed: false, granularity: '' };
address.unconfirmed = false;
address.message = '';
address.location = null;
if (g.error || !g.result) {
  const e = g.error || {};
  address.message = 'Google address check unavailable: ' + s(e.message || e.description || (typeof e === 'string' ? e : '') || 'no result').slice(0, 200);
} else {
  const r = g.result;
  const v = r.verdict || {};
  const ad = r.address || {};
  const gran = s(v.validationGranularity);
  // PREMISE / SUB_PREMISE: Google found the building; anything coarser
  // (PREMISE_PROXIMITY, BLOCK, ROUTE, OTHER) means the street number or
  // street could not be matched, common for rural routes.
  const confirmed = (gran === 'PREMISE' || gran === 'SUB_PREMISE') && v.addressComplete !== false && !v.hasUnconfirmedComponents;
  address.google = { checked: true, confirmed, granularity: gran };
  if (!confirmed) {
    const NAMES = { street_number: 'street number', route: 'street', locality: 'city', administrative_area_level_1: 'state',
      postal_code: 'zip', subpremise: 'unit or box', point_of_interest: 'place name', country: 'country' };
    const words = (list) => [...new Set((list || []).map((t) => NAMES[t] || String(t).replace(/_/g, ' ')))].join(', ');
    const missing = words(ad.missingComponentTypes);
    const unconf = words(ad.unconfirmedComponentTypes);
    address.unconfirmed = true;
    address.message = 'Google could not confirm this street address' +
      (missing ? '; missing: ' + missing : '') + (unconf ? '; not confirmed: ' + unconf : '') + '.';
  }
  const loc = r.geocode && r.geocode.location;
  if (loc && isFinite(loc.latitude) && isFinite(loc.longitude) && ['PREMISE', 'SUB_PREMISE', 'PREMISE_PROXIMITY'].includes(s(r.geocode.granularity || gran))) {
    address.location = { lat: Number(loc.latitude), lng: Number(loc.longitude) };
  }
  // The standardized address: USPS (US / PR, enableUspsCass), else Google's
  // postal address. Zip stays 5 digits unless the rep typed 9.
  const u = (r.uspsData && r.uspsData.standardizedAddress) || {};
  const pa = ad.postalAddress || {};
  const zipOf = (zip5, ext) => {
    const z = s(zip5).replace(/[\s-]/g, '');
    return input.zip.length === 9 && ext ? z.slice(0, 5) + s(ext) : (input.zip.length === 9 ? z : z.slice(0, 5));
  };
  const got = u.firstAddressLine
    ? { address: s(u.firstAddressLine), address2: s(u.secondAddressLine), city: s(u.city), state: s(u.state), zip: zipOf(u.zipCode, u.zipCodeExtension) }
    : { address: s((pa.addressLines || [])[0]), address2: s((pa.addressLines || [])[1]), city: s(pa.locality), state: s(pa.administrativeArea), zip: zipOf(pa.postalCode) };
  const differs = (got.address && !same(got.address, input.address)) || (got.address2 && !same(got.address2, input.address2)) ||
    (got.city && !same(got.city, input.city)) || (got.state && !same(got.state, input.state)) ||
    (got.zip && got.zip !== input.zip);
  // Only a confirmed address is worth suggesting. Eclipse's own city list
  // (a failed Eclipse check) is kept as extra choices after Google's city.
  if (confirmed && differs && got.address && got.city) {
    const eclipseCities = (address.suggestion && address.suggestion.cities) || [];
    address.suggestion = {
      address: got.address, address2: got.address2 || input.address2,
      city: got.city, cities: [...new Set([got.city.toUpperCase()].concat(eclipseCities.map((c) => c.toUpperCase())))],
      state: got.state || input.state, zip: got.zip || input.zip, source: 'google',
    };
  }
}

// ── Duplicates ─────────────────────────────────────────────────────────
const SUFFIX = { street: 'st', avenue: 'ave', av: 'ave', road: 'rd', drive: 'dr', boulevard: 'blvd', lane: 'ln',
  court: 'ct', highway: 'hwy', parkway: 'pkwy', place: 'pl', circle: 'cir', terrace: 'ter', suite: 'ste',
  north: 'n', south: 's', east: 'e', west: 'w', northeast: 'ne', northwest: 'nw', southeast: 'se', southwest: 'sw',
  route: 'rte', county: 'co' };
const street = (v) => s(v).toLowerCase().replace(/[.,#]/g, ' ').split(/\s+/).filter(Boolean)
  .map((w) => SUFFIX[w] || w).join(' ');
// Company names: drop HubSpot's " - Bill/Ship - AG - City, ST - 12345"
// tail, punctuation and common endings.
const company = (v) => s(v).split(' - ')[0].toLowerCase().replace(/[^a-z0-9 ]/g, ' ')
  .split(/\s+/).filter((w) => w && !['inc', 'llc', 'co', 'corp', 'company', 'ltd', 'the'].includes(w)).join(' ');

const want = { street: street(input.address), zip5: input.zip.slice(0, 5), name: company(input.name), domain: input.domain };
// Same kind only (2026-10-30, on request): a ship-to only matches ship-tos,
// a bill-to only matches bill-tos, bill + ship matches either. A record with
// no billto_shipto_flag (HubSpot only, never in Eclipse) is always kept.
const flags = input.flags || [];
const sameKind = (flag) => {
  const have = s(flag).split(';').map(s).filter(Boolean);
  return !flags.length || !have.length || flags.some((f) => have.includes(f));
};
const seen = {};
const duplicates = [];
let searchError = '';
for (const node of ['HubSpot: same zip or domain', 'HubSpot: same name']) {
  for (const it of $(node).all()) {
    const r = it.json || {};
    if (r.error) { searchError = searchError || s(r.error); continue; }
    const list = Array.isArray(r.results) ? r.results : (r.id ? [r] : []);
    for (const c of list) {
      const id = String(c.id || '');
      if (!id || seen[id]) continue;
      const p = c.properties || {};
      if (!sameKind(p.billto_shipto_flag)) continue;
      const reasons = [];
      if (want.street && street(p.address) === want.street && s(p.zip).slice(0, 5) === want.zip5) reasons.push('Same address');
      if (want.domain && s(p.domain).toLowerCase() === want.domain) reasons.push('Same domain');
      const n = company(p.name);
      if (want.name && n && (n === want.name || (want.name.length >= 4 && (n.includes(want.name) || want.name.includes(n))))) reasons.push('Similar name');
      if (!reasons.length) continue;
      seen[id] = true;
      duplicates.push({
        e_customer_id: s(p.e_customer_id),
        hs_id: id,
        name: s(p.name),
        address: [s(p.address), s(p.address2), [s(p.city), [s(p.state), s(p.zip)].filter(Boolean).join(' ')].filter(Boolean).join(', ')].filter(Boolean).join(', '),
        reasons,
      });
    }
  }
}
// Address matches first, then domain, then name.
const rank = (d) => (d.reasons.includes('Same address') ? 0 : d.reasons.includes('Same domain') ? 1 : 2);
duplicates.sort((x, y) => rank(x) - rank(y));

return [{ json: { statusCode: 200, body: { address, duplicates: duplicates.slice(0, 10), duplicate_check_error: searchError } } }];
